package com.siam.deviceinfo; import android.os.Bundle;import android.content.*;import android.content.pm.*;import com.siam.deviceinfo.helper.*;import java.util.*;
public class DeviceActivity extends BaseScreenActivity {protected int layout(){return R.layout.activity_device;} protected String title(){return "ডিভাইস তথ্য";} public void onCreate(Bundle b){super.onCreate(b);heading("ফোনের আসল তথ্য");for(Map.Entry<String,String>e:DeviceInfoHelper.getInfo(this).entrySet())line(e.getKey(),e.getValue());heading("ইনস্টল করা অ্যাপ");note("Android-এর package visibility সীমা অনুযায়ী কেবল চালু করা যায় এমন অ্যাপ দেখানো হয়।");PackageManager pm=getPackageManager();List<ApplicationInfo> apps=pm.getInstalledApplications(0);int count=0;for(ApplicationInfo a:apps){if(pm.getLaunchIntentForPackage(a.packageName)!=null){line(pm.getApplicationLabel(a).toString(),a.packageName);if(++count>=30)break;}}if(count==0)note("দেখানোর মতো অ্যাপ নেই।");}
}
